package br.com.sistemacardapio.catalogo;import java.util.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import jakarta.validation.Valid;
@RestController@RequestMapping("/api/produtos/{produtoId}/variacoes")@PreAuthorize("hasRole('ADMIN_EMPRESA')")public class ProdutoVariacaoController{private final ProdutoVariacaoService s;public ProdutoVariacaoController(ProdutoVariacaoService s){this.s=s;}@GetMapping public List<ProdutoVariacaoService.Response>listar(@PathVariable UUID produtoId){return s.listar(produtoId);}@PostMapping@ResponseStatus(HttpStatus.CREATED)public ProdutoVariacaoService.Response criar(@PathVariable UUID produtoId,@Valid@RequestBody ProdutoVariacaoService.Request r){return s.criar(produtoId,r);}@PutMapping("/{id}")public ProdutoVariacaoService.Response atualizar(@PathVariable UUID produtoId,@PathVariable UUID id,@Valid@RequestBody ProdutoVariacaoService.Request r){return s.atualizar(produtoId,id,r);}}
